/**
 * Interface translations. Keys are the English strings themselves, so the
 * source code stays readable (`t("Become a host")`) and English needs no
 * dictionary. A language without a given key falls back to English.
 *
 * `{name}`-style placeholders are substituted by `t(key, vars)`.
 */

export type Lang = "en" | "hi" | "mr" | "kn" | "es" | "fr" | "de" | "ja" | "pt" | "it" | "id" | "zh" | "ko" | "nl";

/** Map a region code like "hi-IN" or "pt-BR" to a dictionary language. */
export function langFromCode(code: string): Lang {
  const base = code.split("-")[0].toLowerCase();
  const known: Lang[] = ["hi", "mr", "kn", "es", "fr", "de", "ja", "pt", "it", "id", "zh", "ko", "nl"];
  return (known as string[]).includes(base) ? (base as Lang) : "en";
}

